class TransferForm(forms.Form):
    amount = forms.DecimalField(min_value=1)

    def clean_amount(self):
        amount = self.cleaned_data["amount"]
        if amount > self.user_balance:
            raise forms.ValidationError("Amount exceeds balance.")
        return amount

def transfer(request):
    form = TransferForm(request.POST or None)
    if request.method == "POST" and form.is_valid():
        amount = form.cleaned_data["amount"]  # converted + validated
        return redirect("transfer-complete")
    return render(request, "transfer.html", {"form": form})

from django.db import transaction

@transaction.atomic
def buy(product_id, quantity):
    product = Product.objects.select_for_update().get(pk=product_id)
    if product.stock < quantity:
        raise OutOfStock(product_id)
    product.stock -= quantity
    product.save(update_fields=["stock"])
    transaction.on_commit(lambda: cache.delete("product-list"))
    return Order.objects.create(product=product, quantity=quantity)

@login_required
def invoice_edit(request, pk):
    # Authentication: login_required
    # Authorization: the owner filter
    invoice = get_object_or_404(Invoice, pk=pk, owner=request.user)
    form = InvoiceForm(request.POST or None, instance=invoice)
    if request.method == "POST" and form.is_valid():
        form.save()
        return redirect("invoice-detail", pk=invoice.pk)
    return render(request, "invoices/edit.html", {"form": form})
